from datetime import datetime, timezone, timedelta
from security_client import SecurityClients
from security_models import SecretRotationSummary

def get_rotation_summary(secret_name_prefix: Optional[str] = None) -> List[SecretRotationSummary]:
    client = SecurityClients.get_aws_secrets_manager_client()
    summaries: List[SecretRotationSummary] = []
    paginator = client.get_paginator('list_secrets')

    try:
        for page in paginator.paginate(Filters=[{'Key': 'name', 'Values': [secret_name_prefix]}] if secret_name_prefix else []):
            for secret_list_entry in page.get('SecretList', []):
                secret_arn = secret_list_entry['ARN']
                secret_name = secret_list_entry['Name']

                describe_response = client.describe_secret(SecretId=secret_arn)

                rotation_enabled = describe_response.get('RotationEnabled', False)
                last_rotated_date_ts = None
                if 'LastRotatedDate' in describe_response:
                    last_rotated_date_ts = describe_response['LastRotatedDate'].timestamp()

                status = "Unknown"
                if rotation_enabled:
                    if 'LastRotatedDate' in describe_response and describe_response['LastRotatedDate'] > datetime.now(timezone.utc) - timedelta(days=365):
                         status = "Active"
                    else:
                        status = "RotationPending" if "AWSPENDING" in describe_response.get("SecretVersionsToStages", {}) else "Active"
                else:
                    status = "RotationDisabled"

                summaries.append(SecretRotationSummary(
                    secret_name=secret_name,
                    arn=secret_arn,
                    last_rotated_date=last_rotated_date_ts,
                    rotation_enabled=rotation_enabled,
                    status=status
                ))
        return summaries
    except Exception as e:
        raise",
