from security_models import SafetyCheckResult
from google.cloud import dlp_v2
from google.api_core.exceptions import GoogleAPIError

def check_secret_for_unsafe_content(project_id: str, text_content: str, info_types: Optional[List[str]] = None) -> SafetyCheckResult:
    client = SecurityClients.get_gcp_dlp_client()

    if info_types is None:
        info_types = [
            "CREDIT_CARD_NUMBER",
            "EMAIL_ADDRESS",
            "IP_ADDRESS",
            "PHONE_NUMBER",
            "US_SOCIAL_SECURITY_NUMBER",
            "PASSWORD",
            "AUTH_TOKEN",
            "API_KEY"
        ]

    inspect_config = {
        "info_types": [{"name": info_type} for info_type in info_types],
        "include_quote": True,
        "min_likelihood": dlp_v2.Likelihood.POSSIBLE,
        "limits": {"max_findings_per_request": 0},
    }

    item = {"value": text_content}

    parent = f"projects/{project_id}/locations/global"

    try:
        response = client.inspect_content(
            request={"parent": parent, "inspect_config": inspect_config, "item": item}
        )

        violations = []
        if response.result.findings:
            for finding in response.result.findings:
                violations.append(f"Found {finding.info_type.name} at likelihood {dlp_v2.Likelihood(finding.likelihood).name}")
            return SafetyCheckResult(is_safe=False, violations=violations)
        else:
            return SafetyCheckResult(is_safe=True)

    except GoogleAPIError as e:
        raise
    except Exception as e:
        raise",
